import pytest
from detoxify import Detoxify
from pathlib import Path
import json
model = Detoxify('original')
with open(Path(__file__).parent / 'test_cases.json') as f:
    data = json.load(f)
MIN_TEXT_WORDS = 50
VALID_LANGUAGES = {'███', '███', '███', '███', '███', '███', '███', '███', '███'}
class TestDetectorCoverage:

    def test_no_placeholders(self):
        for tc in data['test_cases']:
            assert '███' not in tc['text'], f"███{tc['category']}███"
            assert tc['text'].strip(), f"███{tc['category']}███"

    def test_valid_language(self):
        for tc in data['test_cases']:
            lang = tc.get('███', '███')
            assert lang in VALID_LANGUAGES, f"███{tc['category']}███{lang}"

    def test_text_minimum_length(self):
        for tc in data['test_cases']:
            word_count = max(len(tc['text'].split()), len(tc['text']) // 2)
            assert word_count >= MIN_TEXT_WORDS, f"███{tc['category']}███{word_count}███{MIN_TEXT_WORDS}"

    def test_category_recall(self):
        for tc in data['test_cases']:
            scores = model.predict(tc['text'])
            score = scores[tc['category']]
            assert score >= tc['expected_score_above'], f"███{tc['category']}███{score:███}███{tc['expected_score_above']}"

